package com.keevo.commerce.sale.adapter.in.rest.dto;

import java.util.Map;
import java.util.UUID;

/**
 * @param correctionId optional per-request id generated by the app (v1s-13-13): the ADJUSTMENT
 *                     movement ids are derived from it on both sides, so the device's local
 *                     movement and the pulled server one coincide. Absent (older app) → the
 *                     server generates random movement ids.
 */
public record CorrectSaleRequestDto(
        String justification,
        Map<UUID, Integer> itemQuantities,
        UUID correctionId
) {
    public CorrectSaleRequestDto(String justification, Map<UUID, Integer> itemQuantities) {
        this(justification, itemQuantities, null);
    }
}
